class FlyoutTooltip extends HTMLElement {
  private flyoutContent: HTMLElement | null;
  private hoverArea: HTMLElement;

  constructor() {
    super();
    this.flyoutContent = this.querySelector('[slot="flyout-content"]');

    this.hoverArea = document.createElement("div");
    this.hoverArea.classList.add("hover-area");
  }

  connectedCallback() {
    const activator = this.querySelector('[slot="activator"]');
    if (activator) {
      activator.addEventListener("mouseenter", this.showTooltip);
      activator.addEventListener("mouseleave", (event: Event) => {
        this.checkHideTooltip(event as MouseEvent);
      });
      activator.addEventListener("focusin", this.showTooltip);
    }

    if (this.flyoutContent) {
      this.flyoutContent.addEventListener("mouseenter", this.showTooltip);
      this.flyoutContent.addEventListener("mouseleave", (event) => {
        this.checkHideTooltip(event);
      });
      this.flyoutContent.addEventListener("focusin", this.showTooltip);
      this.flyoutContent.addEventListener("focusout", (event) => {
        this.checkHideTooltip(event as FocusEvent);
      });
    }

    if (this.hoverArea) {
      this.hoverArea.addEventListener("mouseenter", this.showTooltip);
      this.hoverArea.addEventListener("mouseleave", (event) => {
        this.checkHideTooltip(event as MouseEvent);
      });
      this.hoverArea.addEventListener("focusin", this.showTooltip);
      this.hoverArea.addEventListener("focusout", () => {
        this.checkHideTooltip();
      });
    }

    document.addEventListener("click", (event) => {
      if (!this.contains(event.target as Node)) {
        this.hideTooltip();
      }
    });
  }

  disconnectedCallback() {
    const activator = this.querySelector('[slot="activator"]');

    if (activator) {
      activator.removeEventListener("mouseenter", this.showTooltip);
      activator.removeEventListener("mouseleave", () => {
        this.checkHideTooltip();
      });
      activator.removeEventListener("focusin", this.showTooltip);
      activator.removeEventListener("focusout", () => {
        this.checkHideTooltip();
      });
    }

    if (this.flyoutContent) {
      this.flyoutContent.removeEventListener("mouseenter", this.showTooltip);
      this.flyoutContent.removeEventListener(
        "mouseleave",
        this.checkHideTooltip,
      );
      this.flyoutContent.removeEventListener("focusin", this.showTooltip);
      this.flyoutContent.removeEventListener("focusout", () => {
        this.checkHideTooltip();
      });
    }
  }

  showTooltip = () => {
    if (!this.flyoutContent) {
      return;
    }

    this.flyoutContent.classList.add("visible");
    this.appendChild(this.hoverArea);
  };

  checkHideTooltip = (event?: MouseEvent | FocusEvent) => {
    if (event && event.type === "mouseleave" && event instanceof MouseEvent) {
      const elements = document.elementsFromPoint(event.clientX, event.clientY);
      if (this.flyoutContent && elements.includes(this.flyoutContent)) {
        return;
      } else if (this.hoverArea && elements.includes(this.hoverArea)) {
        return;
      }
      this.hideTooltip();
      return;
    }

    if (event && event.type == "focusout" && event instanceof FocusEvent) {
      // Needs a small timeout to account for cursor transition during keyboard focus.
      setTimeout(() => {
        if (!this.contains(document.activeElement)) {
          this.hideTooltip();
        }
      }, 10);
    }
  };

  hideTooltip = () => {
    if (this.flyoutContent) {
      this.flyoutContent.classList.remove("visible");

      if (this.contains(this.hoverArea as Node)) {
        this.removeChild(this.hoverArea);
      }
    }
  };
}

window.customElements.define("flyout-tooltip", FlyoutTooltip);
